package com.midtermwork;
import org.junit.Test;
import static org.junit.Assert.*;
public class RecallChecks {
 private void resolve(GameWorld w){while(w.choosingSkill())w.skipLearning();}
 private void learn(GameWorld w,GameWorld.Skill skill,int slot){w.collectItem(GameWorld.Item.TM);assertTrue(w.tmSelecting);assertTrue(w.chooseTm(skill));assertTrue(w.learnInto(slot));}
 private void ticks(GameWorld w,int n){for(int i=0;i<n;i++)w.step(1f/60,0,false,false);}
 @Test public void replacedMovesCanBeRecalledForFree(){GameWorld w=new GameWorld();learn(w,GameWorld.Skill.FIRE_PUNCH,0);learn(w,GameWorld.Skill.THUNDER_PUNCH,0);assertFalse(w.knows(GameWorld.Skill.FIRE_PUNCH));assertTrue(w.learnedBefore(GameWorld.Skill.FIRE_PUNCH));assertTrue(w.openRecall());assertTrue(w.chooseRecall(GameWorld.Skill.FIRE_PUNCH));assertTrue(w.learnInto(2));assertEquals(GameWorld.Skill.FIRE_PUNCH,w.skillAt(2));assertEquals(0,w.itemCount(GameWorld.Item.TM));assertFalse(w.tmOptions().contains(GameWorld.Skill.FIRE_PUNCH));}
 @Test public void equippingAnAlreadyEquippedMoveSwapsItsSlotAndCooldown(){GameWorld w=new GameWorld();w.skillCooldowns[0]=1.2f;w.skillCooldowns[1]=2.4f;w.openRecall();w.chooseRecall(GameWorld.Skill.SCRATCH);assertTrue(w.learnInto(1));assertEquals(GameWorld.Skill.GROWL,w.skillAt(0));assertEquals(GameWorld.Skill.SCRATCH,w.skillAt(1));assertEquals(2.4f,w.skillCooldowns[0],0);assertEquals(1.2f,w.skillCooldowns[1],0);}
 @Test public void swappingAwayAndBackDoesNotResetCooldown(){GameWorld w=new GameWorld();w.enemies.clear();learn(w,GameWorld.Skill.FIRE_PUNCH,0);assertTrue(w.trySkill(0));ticks(w,40);float remaining=w.skillCooldowns[0];assertTrue(w.openRecall());w.chooseRecall(GameWorld.Skill.SCRATCH);w.learnInto(0);ticks(w,20);assertTrue(w.openRecall());w.chooseRecall(GameWorld.Skill.FIRE_PUNCH);w.learnInto(2);assertTrue(w.skillCooldowns[2]>0&&w.skillCooldowns[2]<remaining);assertFalse(w.trySkill(2));ticks(w,160);assertTrue(w.trySkill(2));}
 @Test public void recallFreezesCombatAndCanBeClosedWithoutChange(){GameWorld w=new GameWorld();assertTrue(w.openRecall());float time=w.elapsed,x=w.x;ticks(w,100);assertEquals(time,w.elapsed,0);assertEquals(x,w.x,0);assertFalse(w.trySkill(0));w.chooseRecall(GameWorld.Skill.GROWL);w.skipLearning();assertTrue(w.recalling);w.skipLearning();assertFalse(w.choosingSkill());assertEquals(GameWorld.Skill.SCRATCH,w.skillAt(0));}
 @Test public void memorySurvivesRetryButSpentTmDoesNotDuplicate(){GameWorld w=new GameWorld();w.collectItem(GameWorld.Item.TM);resolve(w);w.collectItem(GameWorld.Item.TM);resolve(w);w.stageComplete=true;w.advanceStage();assertTrue(w.openTm());w.chooseTm(GameWorld.Skill.FIRE_PUNCH);w.learnInto(0);assertEquals(1,w.itemCount(GameWorld.Item.TM));w.hp=0;assertTrue(w.retryStage());assertTrue(w.learnedBefore(GameWorld.Skill.FIRE_PUNCH));assertEquals(1,w.itemCount(GameWorld.Item.TM));w.openRecall();w.chooseRecall(GameWorld.Skill.FIRE_PUNCH);assertTrue(w.learnInto(0));assertEquals(1,w.itemCount(GameWorld.Item.TM));}
 @Test public void levelLearnedMovesStayInMemoryAndRestartStartsFresh(){GameWorld w=new GameWorld();while(w.level<4)w.addExperience(w.xpRequired()-w.xp);assertEquals(GameWorld.Skill.EMBER,w.pendingSkill());w.learnInto(0);w.hp=0;w.retryStage();assertTrue(w.learnedBefore(GameWorld.Skill.EMBER));w.openRecall();w.chooseRecall(GameWorld.Skill.EMBER);assertTrue(w.learnInto(2));w.restart();assertFalse(w.learnedBefore(GameWorld.Skill.EMBER));assertEquals(2,w.recallOptions().size());}
 @Test public void dashChargesAreNotRefilledByReequipping(){GameWorld w=new GameWorld();w.mapIndex=4;w.stageComplete=true;w.advanceStage();w.boss.hp=0;w.x=w.exitX()+2;w.step(1f/60,0,false,false);w.chooseBuildReward(GameWorld.BuildPath.DASH);w.chooseItemReward(0);w.advanceStage();w.enemies.clear();w.spikes.clear();w.blocks.clear();w.blocks.add(new GameWorld.Block(0,0,4500,112));learn(w,GameWorld.Skill.FLAME_CHARGE,0);assertTrue(w.trySkill(0));ticks(w,35);assertEquals(1,w.skillCharges(0));w.openRecall();w.chooseRecall(GameWorld.Skill.SCRATCH);w.learnInto(0);w.openRecall();w.chooseRecall(GameWorld.Skill.FLAME_CHARGE);w.learnInto(2);assertEquals(1,w.skillCharges(2));assertTrue(w.skillCooldowns[2]>0);}
 @Test public void unknownMovesCannotBeRecalledAndCastingCannotBeInterrupted(){GameWorld w=new GameWorld();w.openRecall();assertFalse(w.chooseRecall(GameWorld.Skill.OVERHEAT));w.skipLearning();w.trySkill(0);assertFalse(w.openRecall());}
}
